// The website is prerendered HTML (url-map.md); it hydrates for the flame motion and the live audit.
export const prerender = true;
// Section entrance on scroll: a 12 px rise with a fade, once (docs/design/motion.md tokens:
// --dur-base and --ease-out). Content is visible without JavaScript and with reduced motion;
// the class that hides it is only added when this runs and motion is allowed.
export function reveal(node: HTMLElement) {
  const reduce =
    matchMedia("(prefers-reduced-motion: reduce)").matches ||
    document.documentElement.hasAttribute("data-reduce-motion");
  if (reduce || !("IntersectionObserver" in window)) return;
  const r = node.getBoundingClientRect();
  if (r.top < innerHeight) return; // already on screen: never hide what the person can see
  node.classList.add("reveal");
  const io = new IntersectionObserver(
    (entries) => {
      for (const e of entries) {
        if (!e.isIntersecting) continue;
        node.classList.add("in");
        io.disconnect();
      }
    },
    { rootMargin: "0px 0px -10% 0px" },
  );
  io.observe(node);
  return { destroy: () => io.disconnect() };
}
// Live deletion audit on the privacy page (SRS-WEB-2, BR-D-7): GET /api/v1/audit, counts only.
// Fails soft: any network error, bad status, bad shape or a slow server gives "down", and the
// page keeps the static audit text.
import { z } from "zod";

export const Audit = z.object({
  at: z.string(),
  pass: z.boolean(),
  stores: z
    .array(
      z.object({
        store: z.string().max(40),
        table: z.string().max(80),
        per_gathering: z.boolean(),
        total_rows: z.number().int().min(0),
        expired_rows: z.number().int().min(0),
      }),
    )
    .max(64),
});
export type AuditT = z.infer<typeof Audit>;

export type AuditView =
  | { s: "down" }
  | { s: "ok"; at: Date; pass: boolean; leftover: number; stores: AuditT["stores"] };

export async function fetchAudit(
  fetchFn: (u: string, i?: RequestInit) => Promise<Response>,
  timeoutMs = 5000,
): Promise<AuditView> {
  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), timeoutMs);
  try {
    const res = await fetchFn("/api/v1/audit", { headers: { accept: "application/json" }, signal: ctl.signal });
    if (!res.ok) return { s: "down" };
    const parsed = Audit.safeParse(await res.json());
    if (!parsed.success) return { s: "down" };
    const at = new Date(parsed.data.at);
    if (Number.isNaN(at.getTime())) return { s: "down" };
    // Passing is about the per-gathering stores (openapi Audit.pass); the others are totals.
    const leftover = parsed.data.stores.filter((s) => s.per_gathering).reduce((n, s) => n + s.expired_rows, 0);
    return { s: "ok", at, pass: parsed.data.pass && leftover === 0, leftover, stores: parsed.data.stores };
  } catch {
    return { s: "down" };
  } finally {
    clearTimeout(timer);
  }
}

/* Website styles (docs/design/06-website.md), from design/prototype/src/routes/site/+page.svelte.
   Global, scoped under .site, so the five pages share one stylesheet. */
.site {
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}
.site main {
  flex: 1;
  outline: none;
}
.site a {
  color: var(--accent-text);
}

.site .skip {
  position: absolute;
  left: 12px;
  top: -80px;
  z-index: 10;
  padding: 12px 16px;
  border-radius: var(--r-md);
  background: var(--c-dusk-900);
  color: var(--c-birch-50) !important;
  font-weight: 700;
}
.site .skip:focus {
  top: 12px;
}

.site .nav {
  position: sticky;
  top: 0;
  z-index: 5;
  display: flex;
  gap: 12px;
  justify-content: space-between;
  align-items: center;
  padding: 6px 20px;
  background: var(--bg); /* solid: text no longer shows through while scrolling (fresh-eyes round 4) */
  border-bottom: 1px solid var(--line);
}
.site .nav .brand {
  display: inline-flex;
  min-height: 44px;
  align-items: center;
}
/* Phones: the links get their own scrolling row under the logo (fresh-eyes #15). */
.site .nav {
  flex-wrap: wrap;
}
.site .nav nav {
  order: 3;
  flex-basis: 100%;
  display: flex;
  gap: 18px;
  overflow-x: auto;
  scrollbar-width: none;
  margin-top: -4px;
}
.site .nav nav::-webkit-scrollbar {
  display: none;
}
.site .nav nav a {
  flex: none;
  min-width: 44px;
  justify-content: center;
  font-size: 0.95rem;
  min-height: 36px;
}
.site .nav nav a,
.site .foot-nav a {
  color: var(--text);
  font-weight: 700;
  text-decoration: none;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
}
.site .nav nav a[aria-current="page"],
.site .foot-nav a[aria-current="page"] {
  text-decoration: underline;
  text-decoration-thickness: 3px;
  text-underline-offset: 6px;
  text-decoration-color: var(--c-maple-700);
}
.site .nav .open {
  min-height: 44px;
  padding: 0 18px;
  display: inline-flex;
  align-items: center;
  border-radius: var(--r-pill);
  background: var(--c-maple-700);
  color: var(--c-birch-50);
  font-weight: 700;
  text-decoration: none;
}

.site .hero {
  position: relative;
  min-height: 620px;
  display: grid;
  align-items: end;
  overflow: hidden;
  background: var(--c-dusk-900);
}
.site .hero-art {
  position: absolute;
  inset: 0;
}
.site .hero-art :is(svg) {
  width: 100%;
  height: 100%;
  display: block;
}
/* The moment, as a real screenshot of the app (5-second clarity). */
.site .hero-shot {
  position: relative;
  z-index: 1;
  justify-self: center;
  margin: 0 0 32px;
}
.site .hero-shot img {
  display: block;
  width: 150px;
  height: auto;
  border-radius: 24px;
  border: 6px solid #111;
  box-shadow: 0 18px 50px rgb(0 0 0 / 0.45);
}
/* Phones: the words and the two buttons come first, the screenshot under them (round 2). */
.site .hero {
  align-content: start;
}
.site .hero-copy {
  order: -1;
  position: relative;
  z-index: 1; /* order also changes paint order: keep the words over the art */
  padding: 24px 20px 28px;
  color: var(--c-birch-50);
  max-width: 640px;
  background: linear-gradient(rgba(22, 35, 58, 0.88) 75%, transparent);
}
.site .kicker {
  margin: 0;
  color: var(--c-gold-300);
  font-weight: 700;
}
.site .hero h1 {
  margin: 8px 0;
}
.site .lead {
  font-size: 1.2rem;
  margin: 0 0 16px;
}
.site .ctas {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.site .cta {
  min-height: 56px;
  padding: 0 22px;
  display: inline-flex;
  align-items: center;
  border-radius: var(--r-pill);
  font-weight: 700;
  text-decoration: none;
  color: var(--c-birch-50) !important;
  border: 2px solid var(--c-birch-50);
}
.site .cta.primary {
  background: var(--c-maple-700);
  border-color: var(--c-maple-700);
}
.site .fine {
  margin: 14px 0 0;
  color: var(--c-gold-300);
  font-weight: 700;
}

.site .band.feat {
  padding-top: 8px; /* follows a band of the same colour: no doubled gap (fresh-eyes round 5) */
}
.site .band {
  padding: 56px 20px;
  max-width: 1080px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.site .band.alt {
  background: var(--surface);
  max-width: none;
}
.site .band.alt > * {
  max-width: 1040px;
  width: 100%;
  margin-left: auto;
  margin-right: auto;
}
.site .band.page-head {
  padding-bottom: 8px;
}
.site h1,
.site h2 {
  margin: 0;
}
.site h3 {
  margin: 8px 0 0;
}
.site .band p {
  margin: 0;
}
.site .more {
  font-weight: 700;
}
.site .more a {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
}

.site .steps {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 28px;
}
.site .steps li {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.site .art {
  height: 230px;
  display: grid;
  place-items: center;
}
/* The how-it-works print needs a width of its own inside the grid (fresh-eyes #7). */
.site .art figure.print {
  width: min(240px, 70vw);
}
.site .art.meter {
  align-content: center;
}
.site .steps .t-heading {
  margin: 0;
  display: flex;
  align-items: center;
  gap: 10px;
}
.site .n {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--lit);
  color: var(--c-ink-900);
  flex: none;
}
.site .steps p {
  margin: 0;
}

.site .states {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
}
.site .states li {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}

.site .two {
  display: grid;
  gap: 24px;
  grid-template-columns: minmax(0, 1fr);
}
.site .band > *,
.site .two > * {
  min-width: 0;
}
.site .checks,
.site .limits {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.site .checks li,
.site .limits li {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}
.site .checks li > :first-child,
.site .limits li > :first-child {
  flex: none;
}

.site .audit {
  background: var(--c-dusk-900);
  color: var(--c-birch-100);
  border-radius: var(--r-lg);
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.site .audit .label {
  margin: 0;
  font-size: 1.05rem;
  line-height: 1.4;
  font-family: var(--font-body);
  font-weight: 700;
  color: var(--c-gold-300);
}
.site .audit p {
  margin: 0;
}
.site .audit table {
  width: 100%;
  border-collapse: collapse;
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 0.9rem;
}
.site .audit caption {
  text-align: left;
  color: var(--c-birch-100);
  padding-bottom: 6px;
}
.site .audit th,
.site .audit td {
  text-align: left;
  padding: 4px 6px;
  border-bottom: 1px solid rgba(246, 241, 231, 0.18);
}
.site .audit td.num,
.site .audit th.num {
  text-align: right;
}
.site .audit .bad {
  color: var(--c-gold-300);
  font-weight: 700;
}

.site pre {
  margin: 0;
  max-width: 100%;
  /* Commands keep their lines; the block scrolls sideways (fresh-eyes #16). */
  white-space: pre;
  padding: 14px;
  border-radius: var(--r-md);
  background: var(--c-dusk-800);
  color: var(--c-birch-100);
  overflow-x: auto;
  font-size: 0.95rem;
