.site .keep {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 12px;
  grid-template-columns: minmax(0, 1fr);
}
.site .keep li {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 14px 16px;
}
.site .keep h4 {
  margin: 0 0 6px;
  font-size: 1.05rem;
}
.site .keep dl {
  margin: 0;
  display: grid;
  gap: 2px;
}
.site .keep dt {
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-top: 6px;
}
.site .keep dd {
  margin: 0;
}
.site .plain {
  margin: 0;
  padding-left: 1.2em;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.site .stack {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.site .stack p {
  margin: 0;
}
.site .run-steps {
  margin: 0;
  padding-left: 1.4em;
  display: flex;
  flex-direction: column;
  gap: 18px;
