.site .foot {
  padding: 20px 20px 40px;
  max-width: 1080px;
  width: 100%;
  margin: 0 auto;
  border-top: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.site .foot-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 20px;
}
.site .foot-line {
  display: flex;
  gap: 12px;
  align-items: center;
}
.site .foot-line img {
  flex: none;
