/* Entrance on scroll (reveal.ts adds .reveal only when motion is allowed). */
.site .reveal {
  opacity: 0;
  transform: translateY(12px);
  transition:
    opacity var(--dur-base, 260ms) var(--ease-out, ease-out),
    transform var(--dur-base, 260ms) var(--ease-out, ease-out);
}
.site .reveal.in {
  opacity: 1;
  transform: none;
}

@media (min-width: 900px) {
  .site .nav {
    flex-wrap: nowrap;
  }
  .site .nav nav {
    order: 0;
