// Builds apps/web/src/routes/(site)/zones.ts from the system zone.tab (IANA tz database).
import fs from "node:fs";
const W = "<project>/flare/.claude/worktrees/agent-a1ac31aa2d2a5e6f7";
const src = fs.readFileSync("/usr/share/zoneinfo/zone.tab", "utf8");
const dms = (s, degLen) => {
  const sign = s[0] === "-" ? -1 : 1;
  const d = Number(s.slice(1, 1 + degLen));
  const m = Number(s.slice(1 + degLen, 3 + degLen));
  const sec = s.length > 3 + degLen ? Number(s.slice(3 + degLen, 5 + degLen)) : 0;
  return sign * (d + m / 60 + sec / 3600);
};
const rows = [];
for (const line of src.split("\n")) {
  if (!line || line.startsWith("#")) continue;
  const [, coord, zone] = line.split("\t");
  const m = coord.match(/^([+-]\d+)([+-]\d+)$/);
  const lat = dms(m[1], 2);
  const lon = dms(m[2], 3);
  rows.push([zone, Math.round(lat * 10) / 10, Math.round(lon * 10) / 10]);
}
rows.sort((a, b) => a[0].localeCompare(b[0]));
const body = rows.map(([z, a, o]) => `${z} ${a} ${o}`).join("|");
const out = `// IANA time zone -> the zone's main city (lat, lon), from the tz database's zone.tab
// (public domain, https://data.iana.org/time-zones/), rounded to 0.1 degree (about 11 km).
// Generated; ${rows.length} zones. Loaded on demand by sunline.ts, never sent anywhere.
export const ZONES = "${body}";
`;
fs.writeFileSync(`${W}/apps/web/src/routes/(site)/zones.ts`, out);
console.log(rows.length, out.length);

