// node peek.mjs <outdir> [w h] [--reduce] [--sel=.story] [--steps=0,0.15,...] [--path=/]
// Screenshots the viewport at story progress points (or a selector scrolled into view).
import fs from "node:fs";
import path from "node:path";
const W = "<project>/flare/.claude/worktrees/agent-a1ac31aa2d2a5e6f7";
const { chromium } = await import(`${W}/node_modules/playwright-core/index.mjs`);
const { serve } = await import(`${W}/apps/web/test/site/serve.ts`);
const arg = (n, d) => (process.argv.find((a) => a.startsWith(`--${n}=`)) ?? `--${n}=${d}`).slice(n.length + 3);
const out = process.argv[2];
const w = Number(process.argv[3] ?? 1280);
const h = Number(process.argv[4] ?? 800);
fs.mkdirSync(out, { recursive: true });
const hub = arg("hub", "connected");
const site = await serve(8894, (p) =>
  p.startsWith("/api/v1/audit")
    ? { status: 200, body: { at: new Date(Date.now() - 12000).toISOString(), pass: true, stores: [{ store: "DS1", table: "gatherings", per_gathering: true, total_rows: 0, expired_rows: 0 }] } }
    : p.startsWith("/api/v1/health")
      ? { status: 200, body: { ok: true, version: "b6fd014293ec", hub, db: "ok" } }
      : p.startsWith("/api/v1/config")
        ? { status: 200, body: { cloud_ai: { photo_opt_in: true } } }
        : null,
);
const browser = await chromium.launch({ channel: "chrome" });
const ctx = await browser.newContext({ viewport: { width: w, height: h }, reducedMotion: process.argv.includes("--reduce") ? "reduce" : "no-preference", timezoneId: "America/Detroit" });
const page = await ctx.newPage();
page.on("console", (m) => m.type() === "error" && console.log("console:", m.text()));
page.on("pageerror", (e) => console.log("pageerror:", e.message));
await page.goto(site.url + arg("path", "/"), { waitUntil: "networkidle" });
const sels = arg("sel", "");
if (sels) {
  for (const [i, s] of sels.split(",").entries()) {
    await page.evaluate((s) => document.querySelector(s)?.scrollIntoView({ block: "start" }), s);
    await page.evaluate(() => scrollBy(0, -110));
    await page.waitForTimeout(Number(arg("wait", "1500")));
    await page.screenshot({ path: path.join(out, `sel-${i}-${w}.jpg`), type: "jpeg", quality: 70 });
  }
} else {
  for (const p of arg("steps", "0,0.12,0.2,0.3,0.6,0.85,0.97").split(",").map(Number)) {
    await page.evaluate((p) => {
      const el = document.querySelector(".story");
      const r = el.getBoundingClientRect();
      const top = r.top + scrollY;
      scrollTo(0, top + p * (r.height - innerHeight));
    }, p);
    await page.waitForTimeout(250);
    const info = await page.evaluate(() => {
      const s = document.querySelector(".story");
      return `${s.dataset.mode} ch=${s.dataset.ch}`;
    });
    console.log(p, info);
    await page.screenshot({ path: path.join(out, `story-${w}-${p}.jpg`), type: "jpeg", quality: 70 });
  }
}
await browser.close();
await site.close();

