// node grid.mjs <dir> <prefix> <out.jpg> [cols] [scale] : contact sheet of screenshots.
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
const W = "<project>/flare/.claude/worktrees/agent-a1ac31aa2d2a5e6f7";
const sharp = createRequire(`${W}/package.json`)("sharp");
const [dir, prefix, out, colsA, scaleA] = process.argv.slice(2);
const cols = Number(colsA ?? 2);
const scale = Number(scaleA ?? 0.5);
const files = fs.readdirSync(dir).filter((f) => f.startsWith(prefix) && f.endsWith(".jpg")).sort();
const meta = await sharp(path.join(dir, files[0])).metadata();
const tw = Math.round(meta.width * scale);
const th = Math.round(meta.height * scale);
const tiles = await Promise.all(files.map((f) => sharp(path.join(dir, f)).resize(tw, th).toBuffer()));
await sharp({ create: { width: tw * cols, height: th * Math.ceil(tiles.length / cols), channels: 3, background: "#fff" } })
  .composite(tiles.map((b, i) => ({ input: b, left: (i % cols) * tw, top: Math.floor(i / cols) * th })))
  .jpeg({ quality: 80 })
  .toFile(out);
console.log(files.join(" "));

